// ── Physics & Render Loop ───────────────────────────────────────
function updateCoins() {
  for (let i = coins.length - 1; i >= 0; i--) {
    const p = coins[i];
    p.age++;
    p.rot += p.vRot;

    if (p.age < p.magnetWait) {
      p.x += p.vx; p.y += p.vy;
      p.vy += 0.38; // gravity
      p.vx *= 0.95; p.vy *= 0.95;
    } else {
      // Magnetic pull toward vault target
      const dx = targetX - p.x, dy = targetY - p.y;
      const dist = Math.hypot(dx, dy);
      if (dist < 26) {
        // Absorbed by Vault
        balance += p.val * 10;
        spawnSpark(targetX, targetY, p.color);
        vaultEl.classList.add('pulse');
        setTimeout(() => vaultEl.classList.remove('pulse'), 90);
        playCoinSound(1.0 + (p.age % 8) * 0.07);
        coins.splice(i, 1);
        continue;
      }
      const pull = Math.min(22, 1.2 + (p.age - p.magnetWait) * 0.85);
      p.vx = (dx / dist) * pull;
      p.vy = (dy / dist) * pull;
      p.x += p.vx; p.y += p.vy;
    }
  }
}

function updateSparks() {
  for (let i = sparks.length - 1; i >= 0; i--) {
    const s = sparks[i];
    s.x += s.vx; s.y += s.vy;
    s.life -= s.decay;
    if (s.life <= 0) sparks.splice(i, 1);
  }
}

function draw() {
  ctx.clearRect(0, 0, W, H);

  // Draw coins with 3D ellipse perspective
  for (const p of coins) {
    ctx.save();
    ctx.translate(p.x, p.y);
    const squish = Math.cos(p.rot);
    ctx.scale(1, Math.abs(squish) * 0.7 + 0.3);

    ctx.beginPath();
    ctx.arc(0, 0, p.size, 0, Math.PI * 2);
    ctx.fillStyle = p.color;
    ctx.shadowColor = p.color;
    ctx.shadowBlur = 10;
    ctx.fill();

    ctx.beginPath();
    ctx.arc(0, 0, p.size * 0.7, 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(255,255,255,0.6)';
    ctx.lineWidth = 1.5;
    ctx.stroke();
    ctx.restore();
  }

  // Draw sparks
  for (const s of sparks) {
    ctx.save();
    ctx.globalAlpha = s.life;
    ctx.beginPath();
    ctx.arc(s.x, s.y, 2.5, 0, Math.PI * 2);
    ctx.fillStyle = s.color;
    ctx.shadowColor = s.color;
    ctx.shadowBlur = 8;
    ctx.fill();
    ctx.restore();
  }

  // Smooth lerp readout
  if (displayBalance < balance) {
    displayBalance += Math.ceil((balance - displayBalance) * 0.2);
    vaultValEl.textContent = displayBalance.toLocaleString();
  }

  updateCoins();
  updateSparks();
  requestAnimationFrame(draw);
}

requestAnimationFrame(draw);
</script>
