126	    osc.frequency.setValueAtTime(140, t);
127	    osc.frequency.exponentialRampToValueAtTime(32, t + 1.2);
128	    gain.gain.setValueAtTime(0.3, t);
129	    gain.gain.exponentialRampToValueAtTime(0.001, t + 1.2);
130	    osc.connect(gain); gain.connect(audioCtx.destination);
131	    osc.start(t); osc.stop(t + 1.2);
132	  } catch(e) {}
133	}
134	
135	function resize() {
136	  W = canvas.width = window.innerWidth;
137	  H = canvas.height = window.innerHeight;
138	  cx = W / 2; cy = H / 2;
139	}
140	window.addEventListener('resize', resize);
141	resize();
142	
143	// ── Particle Ingestion ──────────────────────────────────────────
144	function injectMotes(count = 30) {
145	  for (let i = 0; i < count; i++) {
146	    const angle = Math.random() * Math.PI * 2;
147	    const dist = Math.min(W, H) * (0.35 + Math.random() * 0.25);
148	    particles.push({
149	      x: cx + Math.cos(angle) * dist,
150	      y: cy + Math.sin(angle) * dist,
151	      angle: angle,
152	      radius: dist,
153	      speed: 1.8 + Math.random() * 3.2,
154	      angularVel: (0.015 + Math.random() * 0.02) * (Math.random() > 0.5 ? 1 : -1),
155	      size: 1.5 + Math.random() * 2.5,
156	      hue: Math.random() > 0.4 ? 195 : 275
157	    });
158	  }
159	  playSiphonTone(180 + charge * 3, 0.15);
160	}
161	
162	function dischargeNova() {
163	  if (charge < 10) return;
164	  shockwaves.push({ r: 40, maxR: Math.max(W, H) * 0.75, alpha: 1 });
165	  playNovaExplosion();
166	  charge = 0;
167	  tierLabelEl.textContent = 'Energy Discharged';
168	}
169	
170	function toggleContinuous() {
171	  isAuto = !isAuto;
172	  const btn = document.getElementById('siphonToggle');
173	  btn.classList.toggle('active', isAuto);
174	  if (isAuto) {
175	    autoInterval = setInterval(() => injectMotes(10), 220);
176	  } else {
177	    clearInterval(autoInterval);
178	  }
179	}
180	
181	// ── Plasma Arc Generator ────────────────────────────────────────
182	function updateArcs() {
183	  if (Math.random() < charge / 80) {
184	    const a1 = Math.random() * Math.PI * 2;
185	    const r1 = 30 + (charge / 100) * 45;
186	    arcs.push({
187	      x1: cx + Math.cos(a1) * r1, y1: cy + Math.sin(a1) * r1,
188	      x2: cx + Math.cos(a1 + 0.6) * (r1 + 25), y2: cy + Math.sin(a1 + 0.6) * (r1 + 25),
189	      life: 5
190	    });
191	  }
192	  for (let i = arcs.length - 1; i >= 0; i--) {
193	    if (--arcs[i].life <= 0) arcs.splice(i, 1);
194	  }
195	}
196	
197	// ── Main Render Loop ────────────────────────────────────────────
198	function draw() {
199	  // Trails fade
200	  ctx.fillStyle = 'rgba(3, 3, 10, 0.22)';

201	  ctx.fillRect(0, 0, W, H);
202	
203	  // Update Particles
204	  for (let i = particles.length - 1; i >= 0; i--) {
205	    const p = particles[i];
206	    p.radius -= p.speed;
207	    p.angle += p.angularVel;
208	    p.x = cx + Math.cos(p.angle) * p.radius;
209	    p.y = cy + Math.sin(p.angle) * p.radius;
210	
211	    // Absorption check
212	    if (p.radius <= 35) {
213	      charge = Math.min(100, charge + 0.12);
214	      particles.splice(i, 1);
215	      continue;
216	    }
217	
218	    ctx.beginPath();
219	    ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
220	    ctx.fillStyle = `hsl(${p.hue}, 90%, 65%)`;
221	    ctx.shadowColor = `hsl(${p.hue}, 90%, 65%)`;
222	    ctx.shadowBlur = 8;
223	    ctx.fill();
224	  }
225	
226	  // Draw Central Siphon Singularity
227	  const coreR = 30 + (charge / 100) * 35;
228	  const pulse = Math.sin(Date.now() * 0.005) * 3;
229	
230	  // Outer Ring Accumulator
231	  ctx.save();
232	  ctx.beginPath();
233	  ctx.arc(cx, cy, 75 + pulse, 0, Math.PI * 2);
234	  ctx.strokeStyle = 'rgba(56,189,248,0.2)';
235	  ctx.lineWidth = 2;
236	  ctx.stroke();
237	
238	  // Progress Arc
239	  ctx.beginPath();
240	  ctx.arc(cx, cy, 75 + pulse, -Math.PI / 2, -Math.PI / 2 + (Math.PI * 2 * (charge / 100)));
241	  ctx.strokeStyle = charge > 80 ? '#f43f5e' : (charge > 40 ? '#a855f7' : '#38bdf8');
242	  ctx.lineWidth = 4;
243	  ctx.shadowColor = ctx.strokeStyle;
244	  ctx.shadowBlur = 14;
245	  ctx.stroke();
246	
247	  // Glowing Core
248	  const grad = ctx.createRadialGradient(cx, cy, 5, cx, cy, coreR);
249	  grad.addColorStop(0, '#ffffff');
250	  grad.addColorStop(0.3, charge > 80 ? '#fb7185' : (charge > 40 ? '#c084fc' : '#38bdf8'));
251	  grad.addColorStop(1, 'rgba(0,0,0,0)');
252	  ctx.fillStyle = grad;
253	  ctx.beginPath();
254	  ctx.arc(cx, cy, coreR + pulse, 0, Math.PI * 2);
255	  ctx.fill();
256	  ctx.restore();
257	
258	  // Draw Plasma Arcs
259	  updateArcs();
260	  ctx.strokeStyle = '#e0f2fe';
261	  ctx.lineWidth = 1.5;
262	  for (const arc of arcs) {
263	    ctx.beginPath();
264	    ctx.moveTo(arc.x1, arc.y1);
265	    ctx.lineTo((arc.x1 + arc.x2) / 2 + (Math.random() - 0.5) * 12, (arc.y1 + arc.y2) / 2 + (Math.random() - 0.5) * 12);
266	    ctx.lineTo(arc.x2, arc.y2);
267	    ctx.stroke();
268	  }
269	
270	  // Shockwaves
271	  for (let i = shockwaves.length - 1; i >= 0; i--) {
272	    const sw = shockwaves[i];
273	    sw.r += 14;
274	    sw.alpha -= 0.025;
275	    if (sw.alpha <= 0) { shockwaves.splice(i, 1); continue; }
276	    ctx.save();
277	    ctx.beginPath();
278	    ctx.arc(cx, cy, sw.r, 0, Math.PI * 2);
279	    ctx.strokeStyle = `rgba(240, 249, 255, ${sw.alpha})`;
280	    ctx.lineWidth = 4;
281	    ctx.shadowColor = '#38bdf8';
282	    ctx.shadowBlur = 20;
283	    ctx.stroke();
284	    ctx.restore();
285	  }
286	
287	  // UI Telemetry updates
288	  chargeValEl.textContent = `${charge.toFixed(1)}%`;
289	  if (charge >= 100) {
290	    tierLabelEl.textContent = 'CRITICAL OVERCHARGE';
291	    tierLabelEl.style.color = '#f43f5e';
292	  } else if (charge > 50) {
293	    tierLabelEl.textContent = 'Hyper-Siphoning Active';
294	    tierLabelEl.style.color = '#c084fc';
295	  } else {
296	    tierLabelEl.textContent = 'Storage Primed';
297	    tierLabelEl.style.color = '#7dd3fc';
298	  }
299	
300	  requestAnimationFrame(draw);
301	}
302	
303	requestAnimationFrame(draw);
304	</script>
305	</body>
306	</html>

