    ctx.shadowColor = `hsl(${p.hue}, 90%, 65%)`;
    ctx.shadowBlur = 8;
    ctx.fill();
  }

  // Draw Central Siphon Singularity
  const coreR = 30 + (charge / 100) * 35;
  const pulse = Math.sin(Date.now() * 0.005) * 3;

  // Outer Ring Accumulator
  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, cy, 75 + pulse, 0, Math.PI * 2);
  ctx.strokeStyle = 'rgba(56,189,248,0.2)';
  ctx.lineWidth = 2;
  ctx.stroke();

  // Progress Arc
  ctx.beginPath();
  ctx.arc(cx, cy, 75 + pulse, -Math.PI / 2, -Math.PI / 2 + (Math.PI * 2 * (charge / 100)));
  ctx.strokeStyle = charge > 80 ? '#f43f5e' : (charge > 40 ? '#a855f7' : '#38bdf8');
  ctx.lineWidth = 4;
  ctx.shadowColor = ctx.strokeStyle;
  ctx.shadowBlur = 14;
  ctx.stroke();

  // Glowing Core
  const grad = ctx.createRadialGradient(cx, cy, 5, cx, cy, coreR);
  grad.addColorStop(0, '#ffffff');
  grad.addColorStop(0.3, charge > 80 ? '#fb7185' : (charge > 40 ? '#c084fc' : '#38bdf8'));
  grad.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(cx, cy, coreR + pulse, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  // Draw Plasma Arcs
  updateArcs();
  ctx.strokeStyle = '#e0f2fe';
  ctx.lineWidth = 1.5;
  for (const arc of arcs) {
    ctx.beginPath();
    ctx.moveTo(arc.x1, arc.y1);
    ctx.lineTo((arc.x1 + arc.x2) / 2 + (Math.random() - 0.5) * 12, (arc.y1 + arc.y2) / 2 + (Math.random() - 0.5) * 12);
    ctx.lineTo(arc.x2, arc.y2);
    ctx.stroke();
  }

  // Shockwaves
  for (let i = shockwaves.length - 1; i >= 0; i--) {
    const sw = shockwaves[i];
    sw.r += 14;
    sw.alpha -= 0.025;
    if (sw.alpha <= 0) { shockwaves.splice(i, 1); continue; }
    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, cy, sw.r, 0, Math.PI * 2);
    ctx.strokeStyle = `rgba(240, 249, 255, ${sw.alpha})`;
    ctx.lineWidth = 4;
    ctx.shadowColor = '#38bdf8';
    ctx.shadowBlur = 20;
    ctx.stroke();
    ctx.restore();
  }

  // UI Telemetry updates
  chargeValEl.textContent = `${charge.toFixed(1)}%`;
