    tierLabelEl.textContent = 'Hyper-Siphoning Active';
    tierLabelEl.style.color = '#c084fc';
  } else {
    tierLabelEl.textContent = 'Storage Primed';
    tierLabelEl.style.color = '#7dd3fc';
  }

  requestAnimationFrame(draw);
}

requestAnimationFrame(draw);
