1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0">
6	<title>Fluid Manifold · Liquid Accumulator</title>
7	<style>
8	* { box-sizing: border-box; margin: 0; padding: 0; }
9	html, body {
10	  width: 100%; height: 100%; overflow: hidden;
11	  background: radial-gradient(circle at 50% 30%, #0d1520 0%, #03060a 100%);
12	  font-family: 'Segoe UI', system-ui, sans-serif;
13	  color: #e2e8f0; user-select: none;
14	}
15	canvas { position: fixed; inset: 0; display: block; }
16	
17	.hud {
18	  position: fixed; inset: 0; pointer-events: none;
19	  display: flex; flex-direction: column; justify-content: space-between;
20	  padding: 24px; z-index: 10;
21	}
22	.header { text-align: center; }
23	.sub-title {
24	  font-size: 11px; letter-spacing: .25em; text-transform: uppercase;
25	  color: #10b981; font-weight: 700;
26	}
27	.main-title {
28	  font-size: 20px; font-weight: 800; letter-spacing: .1em;
29	  color: #ecfdf5; text-shadow: 0 0 16px rgba(16,185,129,0.4);
30	}
31	
32	/* ── Tank Telemetry ── */
33	.tank-telemetry {
34	  position: absolute; right: 30px; top: 50%;
35	  transform: translateY(-50%); pointer-events: auto;
36	  display: flex; flex-direction: column; gap: 12px;
37	  background: rgba(6, 15, 23, 0.85); border: 1px solid rgba(16,185,129,0.3);
38	  padding: 16px 20px; border-radius: 14px;
39	}
40	.stat-row { display: flex; flex-direction: column; }
41	.stat-lbl { font-size: 10px; letter-spacing: .15em; color: #6ee7b7; text-transform: uppercase; }
42	.stat-num { font-size: 20px; font-weight: 800; font-family: monospace; color: #fff; }
43	
44	/* ── Controls ── */
45	.controls {
46	  pointer-events: auto; display: flex; justify-content: center;
47	  gap: 12px; flex-wrap: wrap; width: 100%;
48	}
49	.btn {
50	  min-height: 52px; padding: 0 22px;
51	  background: rgba(6, 20, 29, 0.85); border: 1.5px solid rgba(16,185,129,0.35);
52	  border-radius: 12px; color: #a7f3d0; font-size: 12px; font-weight: 700;
53	  letter-spacing: .12em; text-transform: uppercase; cursor: pointer;
54	  transition: all .15s ease; box-shadow: 0 4px 16px rgba(0,0,0,0.5);
55	  display: flex; align-items: center; justify-content: center;
56	}
57	.btn:hover {
58	  background: #0f3b33; border-color: #34d399; color: #fff;
59	  box-shadow: 0 0 22px rgba(16,185,129,0.4); transform: translateY(-2px);
60	}
61	.btn:active { transform: translateY(1px); }
62	</style>
63	</head>
64	<body>
65	<canvas id="c"></canvas>
66	
67	<div class="hud">
68	  <div class="header">
69	    <div class="sub-title">Hydraulic Bio-Reservoir</div>
70	    <div class="main-title">Volumetric Fluid Accumulator</div>

71	  </div>
72	
73	  <div class="tank-telemetry">
74	    <div class="stat-row">
75	      <span class="stat-lbl">Accumulated Volume</span>
76	      <span class="stat-num" id="volVal">0 / 2,500 mL</span>
77	    </div>
78	    <div class="stat-row">
79	      <span class="stat-lbl">Hydrostatic Pressure</span>
80	      <span class="stat-num" id="pressVal">1.02 bar</span>
81	    </div>
82	    <div class="stat-row">
83	      <span class="stat-lbl">Fluid Purity</span>
84	      <span class="stat-num" style="color: #34d399;">99.8% Quantum</span>
85	    </div>
86	  </div>
87	
88	  <div class="controls">
89	    <button class="btn" onclick="injectLiquid(10)">💧 Inject (+10%)</button>
90	    <button class="btn" onclick="injectLiquid(30)">🌊 Flood Surge (+30%)</button>
91	    <button class="btn" onclick="cycleFluid()">🧪 Swap Fluid Matrix</button>
92	    <button class="btn" onclick="drainTank()">⚠️ Flush Purge</button>
93	  </div>
94	</div>
95	
96	<script>
97	const canvas = document.getElementById('c');
98	const ctx = canvas.getContext('2d');
99	const volValEl = document.getElementById('volVal');
100	const pressValEl = document.getElementById('pressVal');
101	let W, H, fillLevel = 0.15, targetLevel = 0.15, pouring = 0;
102	const TANK = { w: 220, h: 420 };
103	const FLUIDS = [
104	  { name: 'Emerald Nanite', color: '#10b981', glow: 'rgba(16,185,129,0.7)', baseHue: 155 },
105	  { name: 'Cerulean Mana',  color: '#0ea5e9', glow: 'rgba(14,165,233,0.7)', baseHue: 198 },
106	  { name: 'Crimson Plasma', color: '#f43f5e', glow: 'rgba(244,63,94,0.7)',  baseHue: 345 },
107	  { name: 'Solar Ambrosia', color: '#f59e0b', glow: 'rgba(245,158,11,0.7)', baseHue: 40 }
108	];
109	let fluidIdx = 0, bubbles = [], splashes = [];
110	
111	// ── Surface Wave Simulation ─────────────────────────────────────
112	const NODES = 42;
113	let springs = Array.from({ length: NODES }, () => ({ y: 0, v: 0 }));
114	
115	// ── Web Audio Synthesizer ───────────────────────────────────────
116	let audioCtx = null;
117	function playLiquidSound(type = 'bubble') {
118	  try {
119	    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
120	    if (audioCtx.state === 'suspended') audioCtx.resume();
121	    const t = audioCtx.currentTime;
122	    const osc = audioCtx.createOscillator();
123	    const gain = audioCtx.createGain();
124	    if (type === 'bubble') {
125	      osc.type = 'sine';
126	      const f = 400 + Math.random() * 400;
127	      osc.frequency.setValueAtTime(f, t);
128	      osc.frequency.exponentialRampToValueAtTime(f * 1.6, t + 0.08);
129	      gain.gain.setValueAtTime(0.08, t);
130	      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.08);
131	      osc.connect(gain); gain.connect(audioCtx.destination);
132	      osc.start(t); osc.stop(t + 0.08);
133	    }
134	  } catch(e) {}
135	}
136	
137	function resize() {
138	  W = canvas.width = window.innerWidth;
139	  H = canvas.height = window.innerHeight;
140	}
141	window.addEventListener('resize', resize);
142	resize();
143	
144	function injectLiquid(amountPercent) {
145	  targetLevel = Math.min(1.0, targetLevel + amountPercent / 100);
146	  pouring = 35;
147	  springs[Math.floor(NODES / 2)].v = 18;
148	  playLiquidSound('bubble');
149	}
150	
151	function drainTank() {
152	  targetLevel = 0.05;
153	  springs[Math.floor(NODES / 2)].v = -14;
154	}
155	
156	function cycleFluid() {
157	  fluidIdx = (fluidIdx + 1) % FLUIDS.length;
158	}
159	
160	// ── Fluid Surface Spring Physics ────────────────────────────────
161	function updateSprings() {
162	  const k = 0.03, d = 0.035;
163	  for (let i = 0; i < NODES; i++) {
164	    const s = springs[i];
165	    s.v += -k * s.y - d * s.v;
166	    s.y += s.v;
167	  }
168	  for (let j = 0; j < 4; j++) {
169	    for (let i = 0; i < NODES; i++) {
170	      if (i > 0) springs[i - 1].v += 0.08 * (springs[i].y - springs[i - 1].y);

171	      if (i < NODES - 1) springs[i + 1].v += 0.08 * (springs[i].y - springs[i + 1].y);
172	    }
173	  }
174	}
175	
176	function updateBubbles(tankX, tankY, surfaceY) {
177	  if (Math.random() < 0.25 && fillLevel > 0.08) {
178	    bubbles.push({
179	      x: tankX + 15 + Math.random() * (TANK.w - 30),
180	      y: tankY + TANK.h - 15,
181	      r: 2 + Math.random() * 4,
182	      vy: 1.2 + Math.random() * 2
183	    });
184	  }
185	  for (let i = bubbles.length - 1; i >= 0; i--) {
186	    const b = bubbles[i];
187	    b.y -= b.vy;
188	    if (b.y <= surfaceY) {
189	      playLiquidSound('bubble');
190	      bubbles.splice(i, 1);
191	    }
192	  }
193	}
194	
195	// ── Draw Tank & Volumetric Shader ───────────────────────────────
196	function draw() {
197	  ctx.clearRect(0, 0, W, H);
198	  fillLevel += (targetLevel - fillLevel) * 0.08;
199	  updateSprings();
200	
201	  const cx = W / 2, cy = H / 2;
202	  const tx = cx - TANK.w / 2, ty = cy - TANK.h / 2;
203	  const currentFluid = FLUIDS[fluidIdx];
204	  const fluidH = TANK.h * fillLevel;
205	  const surfaceBaseY = ty + TANK.h - fluidH;
206	
207	  // Draw Inflow Stream if pouring
208	  if (pouring > 0) {
209	    pouring--;
210	    ctx.save();
211	    ctx.beginPath();
212	    ctx.moveTo(cx - 3, ty - 60);
213	    ctx.lineTo(cx + 3, ty - 60);
214	    ctx.lineTo(cx + 4, surfaceBaseY);
215	    ctx.lineTo(cx - 4, surfaceBaseY);
216	    ctx.fillStyle = currentFluid.color;
217	    ctx.shadowColor = currentFluid.glow;
218	    ctx.shadowBlur = 15;
219	    ctx.fill();
220	    ctx.restore();
221	    if (Math.random() < 0.3) springs[Math.floor(NODES / 2)].v += 4;
222	  }
223	
224	  // Draw Glass Backplate
225	  ctx.save();
226	  ctx.fillStyle = 'rgba(10, 20, 32, 0.6)';
227	  ctx.strokeStyle = 'rgba(255,255,255,0.15)';
228	  ctx.lineWidth = 3;
229	  ctx.beginPath();
230	  ctx.roundRect(tx, ty, TANK.w, TANK.h, 24);
231	  ctx.fill();
232	  ctx.stroke();
233	
234	  // Clip inside tank for Fluid
235	  ctx.save();
236	  ctx.beginPath();
237	  ctx.roundRect(tx, ty, TANK.w, TANK.h, 24);
238	  ctx.clip();
239	
240	  // Draw Liquid Body
241	  const step = TANK.w / (NODES - 1);
242	  ctx.beginPath();
243	  ctx.moveTo(tx, ty + TANK.h);
244	  for (let i = 0; i < NODES; i++) {
245	    const px = tx + i * step;
246	    const py = surfaceBaseY + springs[i].y;
247	    if (i === 0) ctx.lineTo(px, py);
248	    else ctx.lineTo(px, py);
249	  }
250	  ctx.lineTo(tx + TANK.w, ty + TANK.h);
251	  ctx.closePath();
252	
253	  const lGrad = ctx.createLinearGradient(0, surfaceBaseY, 0, ty + TANK.h);
254	  lGrad.addColorStop(0, currentFluid.color);
255	  lGrad.addColorStop(1, 'rgba(3, 8, 14, 0.95)');
256	  ctx.fillStyle = lGrad;
257	  ctx.shadowColor = currentFluid.glow;
258	  ctx.shadowBlur = 24;
259	  ctx.fill();
260	
261	  // Draw Bubbles
262	  updateBubbles(tx, ty, surfaceBaseY);
263	  ctx.fillStyle = 'rgba(255,255,255,0.7)';
264	  for (const b of bubbles) {
265	    ctx.beginPath();
266	    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
267	    ctx.fill();
268	  }
269	  ctx.restore(); // end clip
270	
