    }
  }
}

function updateBubbles(tankX, tankY, surfaceY) {
  if (Math.random() < 0.25 && fillLevel > 0.08) {
    bubbles.push({
      x: tankX + 15 + Math.random() * (TANK.w - 30),
      y: tankY + TANK.h - 15,
      r: 2 + Math.random() * 4,
      vy: 1.2 + Math.random() * 2
    });
  }
  for (let i = bubbles.length - 1; i >= 0; i--) {
    const b = bubbles[i];
    b.y -= b.vy;
    if (b.y <= surfaceY) {
      playLiquidSound('bubble');
      bubbles.splice(i, 1);
    }
  }
}

// ── Draw Tank & Volumetric Shader ───────────────────────────────
function draw() {
  ctx.clearRect(0, 0, W, H);
  fillLevel += (targetLevel - fillLevel) * 0.08;
  updateSprings();

  const cx = W / 2, cy = H / 2;
  const tx = cx - TANK.w / 2, ty = cy - TANK.h / 2;
  const currentFluid = FLUIDS[fluidIdx];
  const fluidH = TANK.h * fillLevel;
  const surfaceBaseY = ty + TANK.h - fluidH;

  // Draw Inflow Stream if pouring
  if (pouring > 0) {
    pouring--;
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(cx - 3, ty - 60);
    ctx.lineTo(cx + 3, ty - 60);
    ctx.lineTo(cx + 4, surfaceBaseY);
    ctx.lineTo(cx - 4, surfaceBaseY);
    ctx.fillStyle = currentFluid.color;
    ctx.shadowColor = currentFluid.glow;
    ctx.shadowBlur = 15;
    ctx.fill();
    ctx.restore();
    if (Math.random() < 0.3) springs[Math.floor(NODES / 2)].v += 4;
  }

  // Draw Glass Backplate
  ctx.save();
  ctx.fillStyle = 'rgba(10, 20, 32, 0.6)';
  ctx.strokeStyle = 'rgba(255,255,255,0.15)';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.roundRect(tx, ty, TANK.w, TANK.h, 24);
  ctx.fill();
  ctx.stroke();

  // Clip inside tank for Fluid
  ctx.save();
  ctx.beginPath();
  ctx.roundRect(tx, ty, TANK.w, TANK.h, 24);
  ctx.clip();

  // Draw Liquid Body
  const step = TANK.w / (NODES - 1);
  ctx.beginPath();
  ctx.moveTo(tx, ty + TANK.h);
  for (let i = 0; i < NODES; i++) {
    const px = tx + i * step;
    const py = surfaceBaseY + springs[i].y;
    if (i === 0) ctx.lineTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.lineTo(tx + TANK.w, ty + TANK.h);
  ctx.closePath();

  const lGrad = ctx.createLinearGradient(0, surfaceBaseY, 0, ty + TANK.h);
  lGrad.addColorStop(0, currentFluid.color);
  lGrad.addColorStop(1, 'rgba(3, 8, 14, 0.95)');
  ctx.fillStyle = lGrad;
  ctx.shadowColor = currentFluid.glow;
  ctx.shadowBlur = 24;
  ctx.fill();

  // Draw Bubbles
  updateBubbles(tx, ty, surfaceBaseY);
  ctx.fillStyle = 'rgba(255,255,255,0.7)';
  for (const b of bubbles) {
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore(); // end clip

  // Glass Front Highlights & Measurement Ticks
  ctx.strokeStyle = 'rgba(255,255,255,0.2)';
  ctx.lineWidth = 1;
  for (let y = ty + 30; y < ty + TANK.h - 20; y += 40) {
    ctx.beginPath();
    ctx.moveTo(tx + 8, y);
    ctx.lineTo(tx + 22, y);
    ctx.stroke();
  }

  // Specular sheen
  const sheenGrad = ctx.createLinearGradient(tx, ty, tx + 60, ty);
  sheenGrad.addColorStop(0, 'rgba(255,255,255,0.25)');
  sheenGrad.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = sheenGrad;
  ctx.fillRect(tx + 6, ty + 6, 26, TANK.h - 12);
  ctx.restore();

  // Telemetry string
  const totalVolume = Math.round(fillLevel * 2500);
  volValEl.textContent = `${totalVolume.toLocaleString()} / 2,500 mL`;
  pressValEl.textContent = `${(1.0 + fillLevel * 2.4).toFixed(2)} bar`;

  requestAnimationFrame(draw);
}

requestAnimationFrame(draw);
</script>
