// ── Render Loop ─────────────────────────────────────────────────
function draw() {
  ctx.fillStyle = 'rgba(2, 2, 8, 0.25)';
  ctx.fillRect(0, 0, W, H);

  // Background Nebula Drift
  ctx.save();
  const grad = ctx.createRadialGradient(cx, cy, 20, cx, cy, Math.min(W, H) * 0.45);
  grad.addColorStop(0, 'rgba(147, 51, 234, 0.12)');
  grad.addColorStop(0.6, 'rgba(59, 130, 246, 0.05)');
  grad.addColorStop(1, 'rgba(0, 0, 0, 0)');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.arc(cx, cy, Math.min(W, H) * 0.45, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  // Draw Constellation Interconnecting Filaments
  ctx.lineWidth = 1.2;
  for (let i = 0; i < stars.length; i++) {
    for (let j = i + 1; j < stars.length; j++) {
      const a = stars[i], b = stars[j];
      const avgCharge = (a.charge + b.charge) / 2;
      ctx.beginPath();
      ctx.moveTo(a.x, a.y);
      ctx.lineTo(b.x, b.y);
      ctx.strokeStyle = `rgba(192, 132, 252, ${0.12 + avgCharge * 0.45})`;
      if (avgCharge > 0.8) {
        ctx.shadowColor = '#c084fc';
        ctx.shadowBlur = 8;
      } else {
        ctx.shadowBlur = 0;
      }
      ctx.stroke();
    }
  }

  // Draw Central Astral Core
  const time = Date.now() * 0.002;
  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, cy, 26 + Math.sin(time * 2) * 3, 0, Math.PI * 2);
  ctx.fillStyle = '#faf5ff';
  ctx.shadowColor = '#c084fc';
  ctx.shadowBlur = 24;
  ctx.fill();

  // Outer rotating mandala rings
  ctx.beginPath();
  ctx.arc(cx, cy, 48, time, time + Math.PI * 1.5);
  ctx.strokeStyle = 'rgba(216, 180, 254, 0.5)';
  ctx.lineWidth = 2;
  ctx.stroke();
  ctx.restore();

  // Update & Draw Pulses
  for (let i = pulses.length - 1; i >= 0; i--) {
    const p = pulses[i];
    p.progress += p.speed;
    const px = p.x1 + (p.x2 - p.x1) * p.progress;
    const py = p.y1 + (p.y2 - p.y1) * p.progress;
    ctx.beginPath();
    ctx.arc(px, py, 4, 0, Math.PI * 2);
    ctx.fillStyle = p.color;
    ctx.shadowColor = p.color;
    ctx.shadowBlur = 12;
    ctx.fill();
    if (p.progress >= 1) pulses.splice(i, 1);
  }

  // Update & Draw Star Nodes
  let synced = 0;
  for (const s of stars) {
    s.charge += (s.targetCharge - s.charge) * 0.08;
    if (s.charge > 0.95) synced++;

    ctx.save();
    ctx.beginPath();
    ctx.arc(s.x, s.y, 10 + s.charge * 6, 0, Math.PI * 2);
    ctx.fillStyle = s.charge > 0.5 ? '#f5d0fe' : '#6b21a8';
    ctx.shadowColor = s.charge > 0.5 ? '#d946ef' : '#7e22ce';
    ctx.shadowBlur = 10 + s.charge * 18;
    ctx.fill();

    // Node glyph ring
    ctx.beginPath();
    ctx.arc(s.x, s.y, 22, 0, Math.PI * 2 * s.charge);
    ctx.strokeStyle = '#e879f9';
    ctx.lineWidth = 2.5;
    ctx.stroke();
    ctx.restore();
  }

  resonanceValEl.textContent = `${synced} / 7 Synced`;
  requestAnimationFrame(draw);
}

requestAnimationFrame(draw);
</script>
</body>

