function fireInstantCharge(seconds) {
  if (phase !== 'idle') return;
  chargeSec = seconds;
  releaseCharge();
}

function releaseCharge() {
  if (chargeSec < 60) { phase = 'idle'; return; }
  phase = 'shattering';
  playReleaseDetonation();
  screenShake = Math.min(28, 6 + (chargeSec / 3600) * 4);
  shockwaves.push({ r: 20, maxR: Math.min(W, H) * 0.6, alpha: 1.0 });

  // Burst into swarm
  const pCount = Math.min(220, Math.max(35, Math.floor(chargeSec / 60)));
  const secPerP = chargeSec / pCount;
  for (let i = 0; i < pCount; i++) {
    const angle = Math.random() * Math.PI * 2;
    const burstSpeed = 5 + Math.random() * 16;
    particles.push({
      x: cx, y: cy, vx: Math.cos(angle) * burstSpeed, vy: Math.sin(angle) * burstSpeed - 2,
      secVal: secPerP, age: 0, magnetWait: 14 + Math.random() * 16,
      size: 3 + Math.random() * 3.5, color: Math.random() > 0.3 ? '#facc15' : '#38bdf8'
    });
  }
  btnLabelEl.textContent = 'SWARM ABSORPTION';
  btnSubEl.textContent = 'FEEDING RESERVOIR';
  chargeSec = 0;
}

function resetPool() {
  permanentSec = 0; displayPermanentSec = 0; particles = []; shockwaves = [];
  phase = 'idle'; poolValEl.textContent = '00:00:00';
  btnLabelEl.textContent = 'HOLD TO COMPRESS'; btnSubEl.textContent = 'RELEASE TO DETONATE';
}

function draw() {
  ctx.save();
  if (screenShake > 0) {
    ctx.translate((Math.random() - 0.5) * screenShake, (Math.random() - 0.5) * screenShake);
    screenShake *= 0.9; if (screenShake < 0.2) screenShake = 0;
  }
  ctx.fillStyle = 'rgba(2, 2, 5, 0.28)'; ctx.fillRect(-20, -20, W + 40, H + 40);

  const t = Date.now() * 0.002;

  // ── PHASE 1: CHARGING STATE ───────────────────────────────────
  if (phase === 'charging' && isHolding) {
    chargeSec += 90; // Accumulate time rapidly under hold
    const chargeProgress = Math.min(1.0, chargeSec / 21600);
    screenShake = 1.5 + chargeProgress * 12;

    btnLabelEl.textContent = `COMPRESSING +${formatHMS(chargeSec)}`;
    btnSubEl.textContent = `PRESSURE: ${(chargeProgress * 100).toFixed(0)}% CRITICAL`;

    // Audio pitch ascends as hold duration lengthens
    if (Math.random() < 0.3) playTone(220 + chargeProgress * 880, 'sawtooth', 0.04, 0.07);

    // Inward Inverted Implosion Rings (Pulling reality into singularity)
    if (Math.random() < 0.4) {
      implodeRings.push({ r: 140 + Math.random() * 60, speed: 4 + chargeProgress * 6, alpha: 0.8 });
    }

    // Draw Implosion Inward Rings
    for (let i = implodeRings.length - 1; i >= 0; i--) {
      const ring = implodeRings[i];
      ring.r -= ring.speed;
      if (ring.r <= 20) { implodeRings.splice(i, 1); continue; }
      ctx.beginPath(); ctx.arc(cx, cy, ring.r, 0, Math.PI * 2);
      ctx.strokeStyle = `rgba(245, 158, 11, ${ring.alpha * (ring.r / 180)})`;
      ctx.lineWidth = 1.8; ctx.stroke();
    }

    // Glowing Central Singularity Orb
    const coreR = 24 + chargeProgress * 36 + Math.sin(t * 16) * (3 + chargeProgress * 4);
    ctx.beginPath(); ctx.arc(cx, cy, coreR, 0, Math.PI * 2);
    ctx.fillStyle = chargeProgress > 0.75 ? '#ffffff' : (chargeProgress > 0.4 ? '#fde047' : '#f97316');
    ctx.shadowColor = '#f59e0b'; ctx.shadowBlur = 25 + chargeProgress * 35; ctx.fill();

    // Floating Staged Numeric Counter at Core
    ctx.font = `900 ${22 + chargeProgress * 8}px 'Consolas', monospace`;
    ctx.fillStyle = '#000'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(`+${formatHMS(chargeSec)}`, cx, cy);
  }

  // ── PHASE 2: FRACTURE & SWARM TO PERMANENT RESERVOIR ──────────
  if (phase === 'shattering') {
    for (let i = particles.length - 1; i >= 0; i--) {
      const p = particles[i]; p.age++;
      if (p.age < p.magnetWait) {
        p.x += p.vx; p.y += p.vy; p.vx *= 0.94; p.vy *= 0.94;
      } else {
        const dx = targetX - p.x, dy = targetY - p.y, dist = Math.hypot(dx, dy);
        if (dist < 26) {
          permanentSec += p.secVal; vaultPodEl.classList.add('hit');
          setTimeout(() => vaultPodEl.classList.remove('hit'), 70);
          playTone(880 + (p.age % 10) * 80, 'sine', 0.05, 0.06);
          particles.splice(i, 1); continue;
        }
        const pull = Math.min(26, 2.0 + (p.age - p.magnetWait) * 0.95);
        p.vx = (dx / dist) * pull; p.vy = (dy / dist) * pull;
        p.x += p.vx; p.y += p.vy;
      }
      ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
      ctx.fillStyle = p.color; ctx.shadowColor = p.color; ctx.shadowBlur = 10; ctx.fill();
    }

    if (particles.length === 0) {
      phase = 'idle';
      btnLabelEl.textContent = 'HOLD TO COMPRESS'; btnSubEl.textContent = 'RELEASE TO DETONATE';
    }
  }

  // Shockwave Rings on release
  for (let i = shockwaves.length - 1; i >= 0; i--) {
    const sw = shockwaves[i]; sw.r += 12; sw.alpha -= 0.035;
    if (sw.alpha <= 0) { shockwaves.splice(i, 1); continue; }
    ctx.beginPath(); ctx.arc(cx, cy, sw.r, 0, Math.PI * 2);
    ctx.strokeStyle = `rgba(254, 240, 138, ${sw.alpha})`; ctx.lineWidth = 4;
    ctx.shadowColor = '#f59e0b'; ctx.shadowBlur = 16; ctx.stroke();
  }

  // Smooth lerp permanent reservoir
  if (displayPermanentSec < permanentSec) {
    displayPermanentSec += Math.ceil((permanentSec - displayPermanentSec) * 0.2);
    poolValEl.textContent = formatHMS(displayPermanentSec);
  }
  ctx.restore();
  requestAnimationFrame(draw);
}
requestAnimationFrame(draw);
</script>
</body>
