114	const canvas = document.getElementById('c'), ctx = canvas.getContext('2d');
115	const poolVaultEl = document.getElementById('poolVault'), poolValEl = document.getElementById('poolVal');
116	const phaseBannerEl = document.getElementById('phaseBanner'), spoolOdometerEl = document.getElementById('spoolOdometer');
117	
118	let W, H, cx, cy, targetX = 0, targetY = 0;
119	let permanentSec = 0, displayPermanentSec = 0;
120	let phase = 'idle'; // 'idle' | 'spooling' | 'shattering'
121	let currentSpoolSec = 0, targetSessionSec = 0, spoolProgress = 0;
122	let screenShake = 0, particles = [], shockwaves = [], arcs = [], audioCtx = null;
