146	    osc.type = 'triangle'; osc.frequency.setValueAtTime(pitch, t);
147	    gain.gain.setValueAtTime(0.04, t); gain.gain.exponentialRampToValueAtTime(0.001, t + 0.03);
148	    osc.connect(gain); gain.connect(audioCtx.destination); osc.start(t); osc.stop(t + 0.03);
149	  } catch(e) {}
150	}
