166	    osc.type = 'sine'; osc.frequency.setValueAtTime(freq, t);
167	    gain.gain.setValueAtTime(0.04, t); gain.gain.exponentialRampToValueAtTime(0.001, t + 0.06);
168	    osc.connect(gain); gain.connect(audioCtx.destination); osc.start(t); osc.stop(t + 0.06);
169	  } catch(e) {}
170	}
171	
172	// ── PHASE 1 TRIGGER: SPOOL RAPIDLY 0s ➔ TARGET ───────────────────
173	function depositSession(totalSeconds) {
174	  if (phase !== 'idle') return;
