196	  screenShake = Math.min(32, 10 + (targetSessionSec / 3600) * 4);
197	  shockwaves.push({ r: 25, maxR: Math.min(W, H) * 0.65, alpha: 1.0 });
198	
199	  // Disperse into particle swarm
200	  const pCount = Math.min(220, Math.max(45, Math.floor(targetSessionSec / 80)));

201	  const secPerP = targetSessionSec / pCount;
202	  for (let i = 0; i < pCount; i++) {
203	    const angle = Math.random() * Math.PI * 2;
204	    const burstSpeed = 5 + Math.random() * 16;
205	    particles.push({
206	      x: cx, y: cy, vx: Math.cos(angle) * burstSpeed, vy: Math.sin(angle) * burstSpeed - 2,
207	      secVal: secPerP, age: 0, magnetWait: 14 + Math.random() * 16,
208	      size: 3 + Math.random() * 3.5, color: Math.random() > 0.35 ? '#facc15' : '#38bdf8'
209	    });
210	  }
211	}
