214	  phase = 'idle'; permanentSec = 0; displayPermanentSec = 0; currentSpoolSec = 0;
215	  particles = []; shockwaves = []; screenShake = 0;
216	  poolValEl.textContent = '00:00:00';
217	  spoolOdometerEl.classList.remove('visible');
218	  phaseBannerEl.className = 'phase-banner';
219	  phaseBannerEl.textContent = 'STANDBY READY';
220	  document.querySelectorAll('.btn').forEach(b => b.disabled = false);
221	}
