223	// ── Render Loop ─────────────────────────────────────────────────
224	function draw() {
225	  ctx.save();
226	  if (screenShake > 0) {
227	    ctx.translate((Math.random() - 0.5) * screenShake, (Math.random() - 0.5) * screenShake);
228	    screenShake *= 0.88; if (screenShake < 0.2) screenShake = 0;
229	  }
230	  ctx.fillStyle = 'rgba(4, 2, 8, 0.28)'; ctx.fillRect(-20, -20, W + 40, H + 40);
231	
232	  const t = Date.now() * 0.002;
233	
234	  // ── PHASE 1: NON-LINEAR SPOOL ACCELERATION ─────────────────────
235	  if (phase === 'spooling') {
236	    spoolProgress += 0.022; // ~1.5 seconds spool duration
237	    currentSpoolSec = Math.round(targetSessionSec * Math.min(1.0, Math.pow(spoolProgress, 1.4)));
238	    spoolOdometerEl.textContent = `+${formatHMS(currentSpoolSec)}`;
239	
240	    screenShake = 1.0 + spoolProgress * 10;
241	    playSpoolClick(400 + spoolProgress * 800);
242	
243	    // Violent Inward Tension Lightning
244	    if (Math.random() < 0.6) {
245	      const a = Math.random() * Math.PI * 2, d = 90 + Math.random() * 100;
246	      arcs.push({ x1: cx + Math.cos(a) * d, y1: cy + Math.sin(a) * d, x2: cx, y2: cy, life: 3 });
247	    }
248	
249	    // Glowing core under tension behind numbers
250	    const coreR = 40 + spoolProgress * 45 + Math.sin(t * 16) * 4;
251	    ctx.beginPath(); ctx.arc(cx, cy, coreR, 0, Math.PI * 2);
252	    ctx.fillStyle = spoolProgress > 0.8 ? '#fef08a' : 'rgba(249, 115, 22, 0.35)';
253	    ctx.shadowColor = '#f97316'; ctx.shadowBlur = 20 + spoolProgress * 30; ctx.fill();
254	
255	    if (spoolProgress >= 0.85) spoolOdometerEl.classList.add('critical');
256	
257	    if (spoolProgress >= 1.0) {
258	      triggerPhase2Shatter();
259	    }
260	  }
261	
262	  // Draw Lightning Arcs
263	  ctx.strokeStyle = '#fde047'; ctx.lineWidth = 1.8;
264	  for (let i = arcs.length - 1; i >= 0; i--) {
265	    const a = arcs[i]; ctx.beginPath(); ctx.moveTo(a.x1, a.y1);
266	    ctx.lineTo((a.x1 + a.x2) / 2 + (Math.random() - 0.5) * 16, (a.y1 + a.y2) / 2 + (Math.random() - 0.5) * 16);
267	    ctx.lineTo(a.x2, a.y2); ctx.stroke();
268	    if (--a.life <= 0) arcs.splice(i, 1);
269	  }
270	
271	  // ── PHASE 2: SHATTER SWARM TO RESERVOIR ────────────────────────
272	  if (phase === 'shattering') {
273	    for (let i = particles.length - 1; i >= 0; i--) {
274	      const p = particles[i]; p.age++;
275	      if (p.age < p.magnetWait) {
276	        p.x += p.vx; p.y += p.vy; p.vx *= 0.94; p.vy *= 0.94;
277	      } else {
278	        const dx = targetX - p.x, dy = targetY - p.y, dist = Math.hypot(dx, dy);
279	        if (dist < 26) {
280	          permanentSec += p.secVal; poolVaultEl.classList.add('absorb');
281	          setTimeout(() => poolVaultEl.classList.remove('absorb'), 70);
282	          playAbsorbTone(880 + (p.age % 10) * 75);
283	          particles.splice(i, 1); continue;
284	        }
285	        const pull = Math.min(26, 2.0 + (p.age - p.magnetWait) * 0.95);
286	        p.vx = (dx / dist) * pull; p.vy = (dy / dist) * pull; p.x += p.vx; p.y += p.vy;
287	      }
288	      ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
289	      ctx.fillStyle = p.color; ctx.shadowColor = p.color; ctx.shadowBlur = 10; ctx.fill();
290	    }
291	
292	    if (particles.length === 0) {
293	      phase = 'idle';
294	      phaseBannerEl.className = 'phase-banner';
295	      phaseBannerEl.textContent = 'SESSION INGESTION COMPLETE · READY';
296	      document.querySelectorAll('.btn').forEach(b => b.disabled = false);
297	    }
298	  }
299	
300	  // Shockwaves
301	  for (let i = shockwaves.length - 1; i >= 0; i--) {
302	    const sw = shockwaves[i]; sw.r += 14; sw.alpha -= 0.035;
303	    if (sw.alpha <= 0) { shockwaves.splice(i, 1); continue; }
304	    ctx.beginPath(); ctx.arc(cx, cy, sw.r, 0, Math.PI * 2);
305	    ctx.strokeStyle = `rgba(254, 240, 138, ${sw.alpha})`; ctx.lineWidth = 4;
306	    ctx.shadowColor = '#f59e0b'; ctx.shadowBlur = 18; ctx.stroke();
307	  }
308	
309	  // Smooth lerp permanent reservoir
310	  if (displayPermanentSec < permanentSec) {
311	    displayPermanentSec += Math.ceil((permanentSec - displayPermanentSec) * 0.2);
312	    poolValEl.textContent = formatHMS(displayPermanentSec);
313	  }
314	  ctx.restore();
315	  requestAnimationFrame(draw);
316	}
317	requestAnimationFrame(draw);
318	</script>
