const phaseBannerEl = document.getElementById('phaseBanner'), spoolOdometerEl = document.getElementById('spoolOdometer');

let W, H, cx, cy, targetX = 0, targetY = 0, permanentSec = 0, displayPermanentSec = 0;
let phase = 'idle', currentSpoolSec = 0, targetSessionSec = 0, spoolProgress = 0;
let screenShake = 0, particles = [], shockwaves = [], arcs = [], audioCtx = null;

function resize() {
  W = canvas.width = window.innerWidth; H = canvas.height = window.innerHeight; cx = W / 2; cy = H / 2;
  const r = poolVaultEl.getBoundingClientRect(); targetX = r.left + r.width / 2; targetY = r.top + r.height / 2;
}
window.addEventListener('resize', resize);
resize();

function formatHMS(sec) {
  const h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60), s = Math.floor(sec % 60);
  return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
}

function initAudio() {
  if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  if (audioCtx.state === 'suspended') audioCtx.resume();
}

function playSpoolClick(pitch) {
  try {
    initAudio();
    const t = audioCtx.currentTime, osc = audioCtx.createOscillator(), gain = audioCtx.createGain();
    osc.type = 'triangle'; osc.frequency.setValueAtTime(pitch, t);
    gain.gain.setValueAtTime(0.04, t); gain.gain.exponentialRampToValueAtTime(0.001, t + 0.03);
    osc.connect(gain); gain.connect(audioCtx.destination); osc.start(t); osc.stop(t + 0.03);
  } catch(e) {}
}

function playShatterDetonation() {
  try {
    initAudio();
    const t = audioCtx.currentTime, osc = audioCtx.createOscillator(), gain = audioCtx.createGain();
    osc.type = 'sawtooth'; osc.frequency.setValueAtTime(160, t); osc.frequency.exponentialRampToValueAtTime(28, t + 0.5);
    gain.gain.setValueAtTime(0.45, t); gain.gain.exponentialRampToValueAtTime(0.001, t + 0.5);
    osc.connect(gain); gain.connect(audioCtx.destination); osc.start(t); osc.stop(t + 0.5);
  } catch(e) {}
}

function playAbsorbTone(freq) {
  try {
    initAudio();
    const t = audioCtx.currentTime, osc = audioCtx.createOscillator(), gain = audioCtx.createGain();
    osc.type = 'sine'; osc.frequency.setValueAtTime(freq, t);
    gain.gain.setValueAtTime(0.04, t); gain.gain.exponentialRampToValueAtTime(0.001, t + 0.06);
    osc.connect(gain); gain.connect(audioCtx.destination); osc.start(t); osc.stop(t + 0.06);
  } catch(e) {}
}

function depositSession(totalSeconds) {
  if (phase !== 'idle') return;
  phase = 'spooling'; targetSessionSec = totalSeconds; currentSpoolSec = 0; spoolProgress = 0;
  spoolOdometerEl.classList.add('visible'); spoolOdometerEl.classList.remove('critical');
  phaseBannerEl.className = 'phase-banner spooling';
  phaseBannerEl.textContent = `PHASE 1: SPOOLING 0s ➔ ${formatHMS(totalSeconds)} PEAK`;
  document.querySelectorAll('.btn').forEach(b => b.disabled = true);
}

function triggerPhase2Shatter() {
  phase = 'shattering';
  spoolOdometerEl.classList.remove('visible');
  phaseBannerEl.className = 'phase-banner shattered';
  phaseBannerEl.textContent = 'PHASE 2: CRITICAL SHATTER ➔ POOL ABSORPTION';
