resize();

function formatDuration(sec) {
  if (!sec || isNaN(sec) || sec < 0) return '0s';
  let s = Math.floor(sec);
  const Y = Math.floor(s / 31536000); s %= 31536000;
  const M = Math.floor(s / 2592000); s %= 2592000;
  const D = Math.floor(s / 86400); s %= 86400;
  const h = Math.floor(s / 3600); s %= 3600;
  const m = Math.floor(s / 60); const rem = s % 60;
  const parts = [];
  if (Y > 0) parts.push(`${Y}Y`);
  if (M > 0) parts.push(`${M}M`);
  if (D > 0) parts.push(`${D}D`);
  if (h > 0) parts.push(`${h}h`);
  if (m > 0) parts.push(`${m}m`);
  if (rem > 0 || parts.length === 0) parts.push(`${rem}s`);
  return parts.join('');
}

function initAudio() {
  if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
  if (audioCtx.state === 'suspended') audioCtx.resume();
}

function playGlassSound(type, freq = 600) {
  try {
    initAudio();
    const t = audioCtx.currentTime, osc = audioCtx.createOscillator(), gain = audioCtx.createGain();
    if (type === 'tick') {
      osc.type = 'sine'; osc.frequency.setValueAtTime(freq, t); gain.gain.setValueAtTime(0.04, t);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.04); osc.start(t); osc.stop(t + 0.04);
    } else if (type === 'shatter') {
      osc.type = 'sawtooth'; osc.frequency.setValueAtTime(1200, t); osc.frequency.exponentialRampToValueAtTime(80, t + 0.45);
      gain.gain.setValueAtTime(0.4, t); gain.gain.exponentialRampToValueAtTime(0.001, t + 0.45); osc.start(t); osc.stop(t + 0.45);
    } else {
      osc.type = 'sine'; osc.frequency.setValueAtTime(freq, t); gain.gain.setValueAtTime(0.05, t);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.08); osc.start(t); osc.stop(t + 0.08);
    }
    osc.connect(gain); gain.connect(audioCtx.destination);
  } catch(e) {}
}

function depositSession(totalSeconds) {
  if (phase !== 'idle') return;
  phase = 'spooling'; targetSessionSec = totalSeconds; currentSpoolSec = 0; spoolProgress = 0;
  cracks = []; spoolOdometerEl.classList.add('visible'); spoolOdometerEl.classList.remove('critical');
  phaseBannerEl.className = 'phase-banner spooling';
  phaseBannerEl.textContent = `PHASE 1: PRISM COMPRESSION 0s ➔ ${formatDuration(totalSeconds)}`;
  document.querySelectorAll('.btn').forEach(b => b.disabled = true);
}

function triggerPhase2Shatter() {
  phase = 'shattering';
  spoolOdometerEl.classList.remove('visible');
  phaseBannerEl.className = 'phase-banner shattered';
  phaseBannerEl.textContent = 'PHASE 2: GLASS FRACTURE ➔ POOL ABSORPTION';
  playGlassSound('shatter');
  screenShake = Math.min(32, 10 + (targetSessionSec / 3600) * 4);
  shockwaves.push({ r: 25, maxR: Math.min(W, H) * 0.65, alpha: 1.0 });

