function depositSession(totalSeconds) {
  if (phase !== 'idle') return;
  phase = 'spooling'; targetSessionSec = totalSeconds; currentSpoolSec = 0; spoolProgress = 0; lingerTimer = 0;
  spoolOdometerEl.classList.add('visible'); spoolOdometerEl.classList.remove('lingering');
  phaseBannerEl.className = 'phase-banner spooling';
  phaseBannerEl.textContent = `PHASE 1: SPOOLING TO ${formatDuration(totalSeconds)}`;
  document.querySelectorAll('.btn').forEach(b => b.disabled = true);
}

function triggerPhase2Shatter() {
  phase = 'shattering';
  spoolOdometerEl.classList.remove('visible');
  spoolOdometerEl.classList.remove('lingering');
  phaseBannerEl.className = 'phase-banner shattered';
  phaseBannerEl.textContent = 'PHASE 2: FRACTURE ➔ POOL ABSORPTION';
  playSound('shatter', 0);
  screenShake = Math.min(32, 10 + (targetSessionSec / 3600) * 4);
  shockwaves.push({ r: 25, maxR: Math.min(W, H) * 0.65, alpha: 1.0 });

  const pCount = Math.min(220, Math.max(45, Math.floor(targetSessionSec / 80)));
  const secPerP = targetSessionSec / pCount;
  for (let i = 0; i < pCount; i++) {
    const a = Math.random() * Math.PI * 2, sp = 5 + Math.random() * 16;
    particles.push({
      x: cx, y: cy, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 2,
      secVal: secPerP, age: 0, magnetWait: 14 + Math.random() * 16,
      size: 3 + Math.random() * 3.5, color: Math.random() > 0.35 ? '#facc15' : '#38bdf8'
    });
  }
}

function resetAll() {
  phase = 'idle'; permanentSec = 0; displayPermanentSec = 0; currentSpoolSec = 0; lingerTimer = 0;
  particles = []; shockwaves = []; screenShake = 0; poolValEl.textContent = '0s';
  spoolOdometerEl.classList.remove('visible'); spoolOdometerEl.classList.remove('lingering');
  phaseBannerEl.className = 'phase-banner'; phaseBannerEl.textContent = 'STANDBY READY';
  document.querySelectorAll('.btn').forEach(b => b.disabled = false);
}

function draw() {
  ctx.save();
  if (screenShake > 0) {
    ctx.translate((Math.random() - 0.5) * screenShake, (Math.random() - 0.5) * screenShake);
    screenShake *= 0.88; if (screenShake < 0.2) screenShake = 0;
  }
  ctx.fillStyle = 'rgba(4, 2, 8, 0.28)'; ctx.fillRect(-20, -20, W + 40, H + 40);
  const t = Date.now() * 0.002;

  // Phase 1A: Non-linear Rapid Spooling
  if (phase === 'spooling') {
    spoolProgress += 0.038;
    currentSpoolSec = Math.round(targetSessionSec * Math.min(1.0, Math.pow(spoolProgress, 1.4)));
    spoolOdometerEl.textContent = `${formatDuration(currentSpoolSec)}`;
    screenShake = 1.0 + spoolProgress * 8;
    playSound('click', 400 + spoolProgress * 700);

    if (Math.random() < 0.6) {
      const a = Math.random() * Math.PI * 2, d = 90 + Math.random() * 100;
      arcs.push({ x1: cx + Math.cos(a) * d, y1: cy + Math.sin(a) * d, x2: cx, y2: cy, life: 3 });
    }
    const coreR = 36 + spoolProgress * 34 + Math.sin(t * 16) * 3;
    ctx.beginPath(); ctx.arc(cx, cy, coreR, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(249, 115, 22, 0.35)'; ctx.shadowColor = '#f97316'; ctx.shadowBlur = 20 + spoolProgress * 25; ctx.fill();

    if (spoolProgress >= 1.0) {
      phase = 'lingering'; lingerTimer = 75; // ~1.25s lingering achievement celebration
      currentSpoolSec = targetSessionSec;
      spoolOdometerEl.textContent = `${formatDuration(targetSessionSec)}`;
      spoolOdometerEl.classList.add('lingering');
      phaseBannerEl.className = 'phase-banner lingering';
      phaseBannerEl.textContent = `CRITICAL ACCUMULATION: ${formatDuration(targetSessionSec)} ACHIEVED`;
      playSound('absorb', 1046.5);
    }
  }

  // Phase 1B: Lingering Peak
  if (phase === 'lingering') {
    lingerTimer--;
    const coreR = 70 + Math.sin(t * 8) * 4;

