  if (phase !== 'idle') return;
  phase = 'spooling'; targetSessionSec = totalSeconds; currentSpoolSec = 0; spoolProgress = 0; lingerTimer = 0;
  cracks = []; spoolOdometerEl.classList.add('visible'); spoolOdometerEl.classList.remove('lingering');
  phaseBannerEl.className = 'phase-banner spooling';
  phaseBannerEl.textContent = `PHASE 1: SPOOLING TO ${formatDuration(totalSeconds)}`;
  document.querySelectorAll('.btn').forEach(b => b.disabled = true);
}

function triggerPhase2Shatter() {
  phase = 'shattering';
  spoolOdometerEl.classList.remove('visible'); spoolOdometerEl.classList.remove('lingering');
  phaseBannerEl.className = 'phase-banner shattered';
  phaseBannerEl.textContent = 'PHASE 2: GLASS FRACTURE ➔ POOL ABSORPTION';
  playGlassSound('shatter');
  screenShake = Math.min(32, 10 + (targetSessionSec / 3600) * 4);
  shockwaves.push({ r: 25, maxR: Math.min(W, H) * 0.65, alpha: 1.0 });

  const pCount = Math.min(220, Math.max(45, Math.floor(targetSessionSec / 80)));
  const secPerP = targetSessionSec / pCount;
  for (let i = 0; i < pCount; i++) {
    const a = Math.random() * Math.PI * 2, sp = 5 + Math.random() * 16;
    shards.push({
      x: cx, y: cy, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 2,
      secVal: secPerP, age: 0, magnetWait: 14 + Math.random() * 16,
      rot: Math.random() * Math.PI * 2, vRot: (Math.random() - 0.5) * 0.4,
      size: 4 + Math.random() * 4, color: Math.random() > 0.4 ? '#e879f9' : '#38bdf8'
    });
  }
}

function resetAll() {
  phase = 'idle'; permanentSec = 0; displayPermanentSec = 0; currentSpoolSec = 0; lingerTimer = 0;
  shards = []; shockwaves = []; cracks = []; screenShake = 0; poolValEl.textContent = '0s';
  spoolOdometerEl.classList.remove('visible'); spoolOdometerEl.classList.remove('lingering');
  phaseBannerEl.className = 'phase-banner'; phaseBannerEl.textContent = 'STANDBY READY';
  document.querySelectorAll('.btn').forEach(b => b.disabled = false);
}

