    const px = Math.cos(a) * size, py = Math.sin(a) * (size * 0.85);
    if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.strokeStyle = '#c084fc'; ctx.lineWidth = 2.5; ctx.shadowColor = '#d946ef'; ctx.shadowBlur = 24; ctx.stroke();
  ctx.restore();
}

