  playGlassSound('shatter');
  screenShake = Math.min(32, 10 + (targetSessionSec / 3600) * 4);
  shockwaves.push({ r: 25, maxR: Math.min(W, H) * 0.65, alpha: 1.0 });

  const pCount = Math.min(220, Math.max(45, Math.floor(targetSessionSec / 80)));
  const secPerP = targetSessionSec / pCount;
  for (let i = 0; i < pCount; i++) {
    const a = Math.random() * Math.PI * 2, sp = 5 + Math.random() * 16;
    shards.push({
      x: cx, y: cy, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 2,
      secVal: secPerP, age: 0, magnetWait: 14 + Math.random() * 16,
      rot: Math.random() * Math.PI * 2, vRot: (Math.random() - 0.5) * 0.4,
      size: 4 + Math.random() * 4, color: Math.random() > 0.4 ? '#e879f9' : '#38bdf8'
    });
  }
}

function resetAll() {
  phase = 'idle'; permanentSec = 0; displayPermanentSec = 0; currentSpoolSec = 0; lingerTimer = 0;
  shards = []; shockwaves = []; cracks = []; screenShake = 0; poolValEl.textContent = '0s';
  spoolOdometerEl.classList.remove('visible'); spoolOdometerEl.classList.remove('lingering');
  phaseBannerEl.className = 'phase-banner'; phaseBannerEl.textContent = 'STANDBY READY';
  document.querySelectorAll('.btn').forEach(b => b.disabled = false);
}

function drawPrismShape(size, rot) {
  ctx.save(); ctx.translate(cx, cy); ctx.rotate(rot); ctx.beginPath();
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * Math.PI * 2;
    const px = Math.cos(a) * size, py = Math.sin(a) * (size * 0.85);
    if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.strokeStyle = '#c084fc'; ctx.lineWidth = 2.5; ctx.shadowColor = '#d946ef'; ctx.shadowBlur = 24; ctx.stroke();
  ctx.restore();
}

function draw() {
  ctx.save();
  if (screenShake > 0) {
    ctx.translate((Math.random() - 0.5) * screenShake, (Math.random() - 0.5) * screenShake);
    screenShake *= 0.88; if (screenShake < 0.2) screenShake = 0;
  }
  ctx.fillStyle = 'rgba(4, 2, 8, 0.28)'; ctx.fillRect(-20, -20, W + 40, H + 40);
  const t = Date.now() * 0.002;

  // Phase 1A: Swift Spool
  if (phase === 'spooling') {
    spoolProgress += 0.038;
    currentSpoolSec = Math.round(targetSessionSec * Math.min(1.0, Math.pow(spoolProgress, 1.4)));
    spoolOdometerEl.textContent = `${formatDuration(currentSpoolSec)}`;
    screenShake = 1.0 + spoolProgress * 8;
    playGlassSound('tick', 500 + spoolProgress * 700);

    drawPrismShape(45 + spoolProgress * 40 + Math.sin(t * 14) * 3, t * 1.5);
    if (spoolProgress >= 1.0) {
      phase = 'lingering'; lingerTimer = 75; // ~1.25s achievement celebration
      currentSpoolSec = targetSessionSec;
      spoolOdometerEl.textContent = `${formatDuration(targetSessionSec)}`;
      spoolOdometerEl.classList.add('lingering');
      phaseBannerEl.className = 'phase-banner lingering';
      phaseBannerEl.textContent = `CRYSTALLIZED VALUE: ${formatDuration(targetSessionSec)} ACHIEVED`;
      playGlassSound('chime', 1046.5);
    }
  }

  // Phase 1B: Lingering Peak with Stress Fractures
  if (phase === 'lingering') {
    lingerTimer--;
    drawPrismShape(85 + Math.sin(t * 8) * 3, t * 0.8);
    if (Math.random() < 0.4) {
      const ca = Math.random() * Math.PI * 2, cd = 10 + Math.random() * 55;
      cracks.push({ x1: cx, y1: cy, x2: cx + Math.cos(ca) * cd, y2: cy + Math.sin(ca) * cd });
    }
    ctx.strokeStyle = '#fff'; ctx.lineWidth = 1.5;
    for (const c of cracks) {
      ctx.beginPath(); ctx.moveTo(c.x1, c.y1); ctx.lineTo(c.x2, c.y2); ctx.stroke();
    }
    screenShake = 1.2;
    if (lingerTimer <= 0) triggerPhase2Shatter();
  }

  // Phase 2: Shard Swarm
  if (phase === 'shattering') {
    for (let i = shards.length - 1; i >= 0; i--) {
      const p = shards[i]; p.age++; p.rot += p.vRot;
      if (p.age < p.magnetWait) {
        p.x += p.vx; p.y += p.vy; p.vx *= 0.94; p.vy *= 0.94;
      } else {
        const dx = targetX - p.x, dy = targetY - p.y, dist = Math.hypot(dx, dy);
        if (dist < 26) {
          permanentSec += p.secVal; poolVaultEl.classList.add('absorb');
          setTimeout(() => poolVaultEl.classList.remove('absorb'), 70);
          playGlassSound('chime', 880 + (p.age % 10) * 80);
          shards.splice(i, 1); continue;
        }
        const pull = Math.min(26, 2.0 + (p.age - p.magnetWait) * 0.95);
        p.vx = (dx / dist) * pull; p.vy = (dy / dist) * pull; p.x += p.vx; p.y += p.vy;
      }
      ctx.save(); ctx.translate(p.x, p.y); ctx.rotate(p.rot);
      ctx.beginPath(); ctx.moveTo(-p.size, -p.size); ctx.lineTo(p.size, 0); ctx.lineTo(0, p.size); ctx.closePath();
      ctx.fillStyle = p.color; ctx.shadowColor = p.color; ctx.shadowBlur = 10; ctx.fill();
      ctx.restore();
    }
    if (shards.length === 0) {
      phase = 'idle'; phaseBannerEl.className = 'phase-banner'; phaseBannerEl.textContent = 'PRISM INGESTION COMPLETE · READY';
      document.querySelectorAll('.btn').forEach(b => b.disabled = false);
    }
  }

