261	function draw() {
262	  ctx.save();
263	  if (screenShake > 0) {
264	    ctx.translate((Math.random() - 0.5) * screenShake, (Math.random() - 0.5) * screenShake);
265	    screenShake *= 0.88; if (screenShake < 0.2) screenShake = 0;
266	  }
267	  ctx.fillStyle = 'rgba(4, 2, 8, 0.28)'; ctx.fillRect(-20, -20, W + 40, H + 40);
268	  const t = Date.now() * 0.002;
269	
270	  // Staged counter lerp
271	  if (stagedSec > 0) {
272	    displayStagedSec += (stagedSec - displayStagedSec) * 0.2;
273	    stagedOdometerEl.textContent = formatDuration(Math.round(displayStagedSec));
274	  }
275	
276	  // Draw Infeed Streaming Motes
277	  for (let i = infeedMotes.length - 1; i >= 0; i--) {
278	    const m = infeedMotes[i]; m.x += m.vx; m.y += m.vy; m.life -= 0.05;
279	    if (m.life <= 0) { infeedMotes.splice(i, 1); continue; }
280	    ctx.beginPath(); ctx.arc(m.x, m.y, 2.5, 0, Math.PI * 2);
281	    ctx.fillStyle = '#fef08a'; ctx.shadowColor = '#f59e0b'; ctx.shadowBlur = 8; ctx.fill();
282	  }
283	
284	  // Draw Lightning Arcs during accumulation
285	  ctx.strokeStyle = '#fde047'; ctx.lineWidth = 1.8;
286	  for (let i = arcs.length - 1; i >= 0; i--) {
287	    const a = arcs[i]; ctx.beginPath(); ctx.moveTo(a.x1, a.y1); ctx.lineTo(a.x2, a.y2); ctx.stroke();
288	    if (--a.life <= 0) arcs.splice(i, 1);
289	  }
290	
291	  // Draw Central Accumulating Block (Grows & charges with each input)
292	  coreScale += (1.0 - coreScale) * 0.05;
293	  const isCharging = stagedSec > 0;
294	  const baseR = 36 * coreScale + (isCharging ? Math.sin(t * 16) * 4 : Math.sin(t * 3) * 2);
295	
296	  ctx.beginPath(); ctx.arc(cx, cy, baseR, 0, Math.PI * 2);
297	  ctx.fillStyle = isCharging ? '#fef08a' : 'rgba(249, 115, 22, 0.45)';
298	  ctx.shadowColor = isCharging ? '#facc15' : '#f97316';
299	  ctx.shadowBlur = isCharging ? 30 : 16;
300	  ctx.fill();
301	
302	  // Shockwaves
303	  for (let i = shockwaves.length - 1; i >= 0; i--) {
304	    const sw = shockwaves[i]; sw.r += 14; sw.alpha -= 0.035;
305	    if (sw.alpha <= 0) { shockwaves.splice(i, 1); continue; }
306	    ctx.beginPath(); ctx.arc(cx, cy, sw.r, 0, Math.PI * 2);
307	    ctx.strokeStyle = `rgba(254, 240, 138, ${sw.alpha})`; ctx.lineWidth = 4;
308	    ctx.shadowColor = '#f59e0b'; ctx.shadowBlur = 18; ctx.stroke();
309	  }
310	
311	  // Phase 2 Particles to Vault
312	  for (let i = particles.length - 1; i >= 0; i--) {
313	    const p = particles[i]; p.age++;
314	    if (p.age < p.magnetWait) {
315	      p.x += p.vx; p.y += p.vy; p.vx *= 0.94; p.vy *= 0.94;
316	    } else {
317	      const dx = targetX - p.x, dy = targetY - p.y, dist = Math.hypot(dx, dy);
318	      if (dist < 26) {
319	        permanentSec += p.secVal; poolVaultEl.classList.add('absorb');
320	        setTimeout(() => poolVaultEl.classList.remove('absorb'), 70);
321	        playSound('absorb', 880 + (p.age % 10) * 75);
322	        particles.splice(i, 1); continue;
323	      }
324	      const pull = Math.min(26, 2.0 + (p.age - p.magnetWait) * 0.95);
325	      p.vx = (dx / dist) * pull; p.vy = (dy / dist) * pull; p.x += p.vx; p.y += p.vy;
326	    }
327	    ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
328	    ctx.fillStyle = p.color; ctx.shadowColor = p.color; ctx.shadowBlur = 10; ctx.fill();
329	  }
330	
331	  // Smooth lerp permanent reservoir
332	  if (displayPermanentSec < permanentSec) {
333	    displayPermanentSec += Math.ceil((permanentSec - displayPermanentSec) * 0.2);
334	    poolValEl.textContent = formatDuration(displayPermanentSec);
335	  }
336	  ctx.restore();
337	  requestAnimationFrame(draw);
338	}
