  stagedLabelEl.className = 'staged-lbl'; stagedLabelEl.textContent = 'STAGED ACCUMULATION';
  stagedOdometerEl.className = 'staged-odometer';
}

function draw() {
  ctx.save();
  if (screenShake > 0) {
    ctx.translate((Math.random() - 0.5) * screenShake, (Math.random() - 0.5) * screenShake);
    screenShake *= 0.88; if (screenShake < 0.2) screenShake = 0;
  }
  ctx.fillStyle = 'rgba(4, 2, 8, 0.28)'; ctx.fillRect(-20, -20, W + 40, H + 40);
  const t = Date.now() * 0.002;

  // Staged counter lerp
  if (stagedSec > 0) {
    displayStagedSec += (stagedSec - displayStagedSec) * 0.2;
    stagedOdometerEl.textContent = formatDuration(Math.round(displayStagedSec));
  }

  // Draw Infeed Streaming Motes
  for (let i = infeedMotes.length - 1; i >= 0; i--) {
    const m = infeedMotes[i]; m.x += m.vx; m.y += m.vy; m.life -= 0.05;
    if (m.life <= 0) { infeedMotes.splice(i, 1); continue; }
    ctx.beginPath(); ctx.arc(m.x, m.y, 2.5, 0, Math.PI * 2);
    ctx.fillStyle = '#fef08a'; ctx.shadowColor = '#f59e0b'; ctx.shadowBlur = 8; ctx.fill();
  }

  // Draw Lightning Arcs during accumulation
  ctx.strokeStyle = '#fde047'; ctx.lineWidth = 1.8;
  for (let i = arcs.length - 1; i >= 0; i--) {
    const a = arcs[i]; ctx.beginPath(); ctx.moveTo(a.x1, a.y1); ctx.lineTo(a.x2, a.y2); ctx.stroke();
    if (--a.life <= 0) arcs.splice(i, 1);
  }

  // Draw Central Accumulating Block (Grows & charges with each input)
  coreScale += (1.0 - coreScale) * 0.05;
  const isCharging = stagedSec > 0;
  const baseR = 36 * coreScale + (isCharging ? Math.sin(t * 16) * 4 : Math.sin(t * 3) * 2);

  ctx.beginPath(); ctx.arc(cx, cy, baseR, 0, Math.PI * 2);
  ctx.fillStyle = isCharging ? '#fef08a' : 'rgba(249, 115, 22, 0.45)';
  ctx.shadowColor = isCharging ? '#facc15' : '#f97316';
  ctx.shadowBlur = isCharging ? 30 : 16;
  ctx.fill();

  // Shockwaves
  for (let i = shockwaves.length - 1; i >= 0; i--) {
    const sw = shockwaves[i]; sw.r += 14; sw.alpha -= 0.035;
    if (sw.alpha <= 0) { shockwaves.splice(i, 1); continue; }
    ctx.beginPath(); ctx.arc(cx, cy, sw.r, 0, Math.PI * 2);
    ctx.strokeStyle = `rgba(254, 240, 138, ${sw.alpha})`; ctx.lineWidth = 4;
    ctx.shadowColor = '#f59e0b'; ctx.shadowBlur = 18; ctx.stroke();
  }

  // Phase 2 Particles to Vault
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i]; p.age++;
    if (p.age < p.magnetWait) {
      p.x += p.vx; p.y += p.vy; p.vx *= 0.94; p.vy *= 0.94;
    } else {
      const dx = targetX - p.x, dy = targetY - p.y, dist = Math.hypot(dx, dy);
      if (dist < 26) {
        permanentSec += p.secVal; poolVaultEl.classList.add('absorb');
        setTimeout(() => poolVaultEl.classList.remove('absorb'), 70);
        playSound('absorb', 880 + (p.age % 10) * 75);
        particles.splice(i, 1); continue;
      }
      const pull = Math.min(26, 2.0 + (p.age - p.magnetWait) * 0.95);
      p.vx = (dx / dist) * pull; p.vy = (dy / dist) * pull; p.x += p.vx; p.y += p.vy;
    }
    ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
    ctx.fillStyle = p.color; ctx.shadowColor = p.color; ctx.shadowBlur = 10; ctx.fill();
  }

  // Smooth lerp permanent reservoir
  if (displayPermanentSec < permanentSec) {
    displayPermanentSec += Math.ceil((permanentSec - displayPermanentSec) * 0.2);
    poolValEl.textContent = formatDuration(displayPermanentSec);
  }
  ctx.restore();
  requestAnimationFrame(draw);
}
