function playSound(type, freq) {
  try {
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    if (audioCtx.state === 'suspended') audioCtx.resume();
    const t = audioCtx.currentTime, osc = audioCtx.createOscillator(), gain = audioCtx.createGain();
    if (type === 'stage') {
      osc.type = 'triangle'; osc.frequency.setValueAtTime(freq, t); gain.gain.setValueAtTime(0.06, t);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.05); osc.start(t); osc.stop(t + 0.05);
    } else if (type === 'shatter') {
      osc.type = 'sawtooth'; osc.frequency.setValueAtTime(180, t); osc.frequency.exponentialRampToValueAtTime(28, t + 0.45);
      gain.gain.setValueAtTime(0.45, t); gain.gain.exponentialRampToValueAtTime(0.001, t + 0.45); osc.start(t); osc.stop(t + 0.45);
    } else {
      osc.type = 'sine'; osc.frequency.setValueAtTime(freq, t); gain.gain.setValueAtTime(0.04, t);
      gain.gain.exponentialRampToValueAtTime(0.001, t + 0.06); osc.start(t); osc.stop(t + 0.06);
    }
    osc.connect(gain); gain.connect(audioCtx.destination);
  } catch(e) {}
}

function stageTime(seconds) {
  stagedSec += seconds;
  coreScale = Math.min(1.7, coreScale + 0.12);
  screenShake = Math.min(18, screenShake + 3);

  for (let i = 0; i < 15; i++) {
    const a = Math.random() * Math.PI * 2, d = 120 + Math.random() * 80;
    infeedMotes.push({
      x: cx + Math.cos(a) * d, y: cy + Math.sin(a) * d,
      vx: -Math.cos(a) * (7 + Math.random() * 5), vy: -Math.sin(a) * (7 + Math.random() * 5), life: 1
    });
  }
  arcs.push({ x1: cx + (Math.random() - 0.5) * 80, y1: cy + (Math.random() - 0.5) * 80, x2: cx, y2: cy, life: 3 });

  stagedLabelEl.className = 'staged-lbl charging';
  stagedLabelEl.textContent = 'CHARGING ACCUMULATION';
  stagedOdometerEl.classList.add('charging');
  playSound('stage', 400 + Math.min(800, (stagedSec / 3600) * 120));

  if (stagedSec >= CRITICAL_CAP) { clearTimeout(idleTimer); triggerPhase2Shatter(); return; }
  clearTimeout(idleTimer);
  idleTimer = setTimeout(() => { if (stagedSec > 0) triggerPhase2Shatter(); }, 1400);
}

function shatterNow() {
  if (stagedSec <= 0) return;
  clearTimeout(idleTimer);
  triggerPhase2Shatter();
}

function triggerPhase2Shatter() {
  const worth = stagedSec; stagedSec = 0; coreScale = 0.4;
  screenShake = Math.min(32, 10 + (worth / 3600) * 3);
  shockwaves.push({ r: 25, maxR: Math.min(W, H) * 0.65, alpha: 1.0 });
  playSound('shatter', 0);

