  const worth = stagedSec; stagedSec = 0; coreScale = 0.4;
  screenShake = Math.min(32, 10 + (worth / 3600) * 3);
  shockwaves.push({ r: 25, maxR: Math.min(W, H) * 0.65, alpha: 1.0 });
  playSound('shatter', 0);

  stagedLabelEl.className = 'staged-lbl burst';
  stagedLabelEl.textContent = 'EXPLOSION WORTH';
  stagedOdometerEl.className = 'staged-odometer burst';
  stagedOdometerEl.textContent = formatDuration(worth);

  const pCount = Math.min(220, Math.max(40, Math.floor(worth / 80)));
  const secPerP = worth / pCount;
  for (let i = 0; i < pCount; i++) {
    const a = Math.random() * Math.PI * 2, sp = 5 + Math.random() * 16;
