// ── Trigger Deposit: Spools 0s ➔ Target, then Explodes Instantly at Peak ──
function depositSession(seconds) {
  isSpooling = true;
  targetSpoolSec = seconds;
  spoolSec = 0;
  spoolProgress = 0;

  clearTimeout(lingerTimeout);
  burstBadgeEl.classList.add('visible');
  burstValEl.classList.remove('lingering');
  burstLabelEl.textContent = 'ACCUMULATING';
  burstValEl.textContent = '0s';
}

// ── Critical Mass Shatter (0ms Delay at Peak) ────────────────────
function triggerShatter() {
  isSpooling = false;
  playSound('shatter', 0);
  screenShake = Math.min(32, 10 + (targetSpoolSec / 3600) * 3);
  shockwaves.push({ r: 25, maxR: Math.min(W, H) * 0.65, alpha: 1.0 });

  // Value below lingers proudly to show what the explosion was worth
  burstLabelEl.textContent = 'EXPLOSION WORTH';
  burstValEl.textContent = formatDuration(targetSpoolSec);
  burstValEl.classList.add('lingering');

  // Spawn particle swarm to pool
  const pCount = Math.min(220, Math.max(45, Math.floor(targetSpoolSec / 80)));
  const secPerP = targetSpoolSec / pCount;
  for (let i = 0; i < pCount; i++) {
    const a = Math.random() * Math.PI * 2, sp = 5 + Math.random() * 16;
    particles.push({
      x: cx, y: cy, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 2,
      secVal: secPerP, age: 0, magnetWait: 14 + Math.random() * 16,
      size: 3 + Math.random() * 3.5, color: Math.random() > 0.35 ? '#facc15' : '#38bdf8'
    });
  }

  // Only the final hours lingers: fades after 2 seconds
  clearTimeout(lingerTimeout);
  lingerTimeout = setTimeout(() => {
    burstBadgeEl.classList.remove('visible');
    burstValEl.classList.remove('lingering');

